package io.quarkus.opentelemetry.runtime.tracing;

import java.io.BufferedReader;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Stream;

/**
 * Regression test for package naming typo: "intrumentation" instead of "instrumentation".
 * 
 * This test scans the source tree for any Java file whose package declaration
 * contains the misspelling "intrumentation" and asserts it is not present.
 * 
 * On /src/new (with the bug): FAILS because classes are in misspelled "intrumentation" packages.
 * On /src/old (without the bug): PASSES because classes were in different packages (grpc/, vertx/, etc.).
 */
public class InstrumentationPackageSpellingTest {

    public static void main(String[] args) throws Exception {
        // Determine the project root from where this test runs
        Path projectRoot = Paths.get(System.getProperty("user.dir")).toAbsolutePath();

        // Walk up to find the actual repo root (has pom.xml and extensions/ dir)
        Path current = projectRoot;
        while (current != null && current.getParent() != null) {
            if (Files.exists(current.resolve("extensions")) && Files.exists(current.resolve("pom.xml"))) {
                projectRoot = current;
                break;
            }
            current = current.getParent();
        }

        Path base = projectRoot.resolve("extensions/opentelemetry/opentelemetry/runtime/src/main/java/io/quarkus/opentelemetry/runtime/tracing");

        if (!Files.exists(base)) {
            System.err.println("FAIL: Source directory not found: " + base);
            System.exit(1);
        }

        List<String> misspelled = new ArrayList<>();

        try (Stream<Path> walk = Files.walk(base)) {
            walk.filter(Files::isRegularFile)
                .filter(p -> p.toString().endsWith(".java"))
                .forEach(p -> checkFile(p, misspelled));
        }

        if (!misspelled.isEmpty()) {
            System.err.println("FAIL: Found Java files with misspelled 'intrumentation' package (should be 'instrumentation'):");
            for (String file : misspelled) {
                System.err.println("  - " + file);
            }
            System.err.println("\nThe correct spelling is 'instrumentation' (with two 'e's), not 'intrumentation'.");
            System.exit(1);
        } else {
            System.out.println("PASS: No misspelled 'intrumentation' package declarations found.");
            System.out.println("All packages use the correct spelling 'instrumentation'.");
            System.exit(0);
        }
    }

    private static void checkFile(Path path, List<String> misspelled) {
        try (BufferedReader reader = Files.newBufferedReader(path, StandardCharsets.UTF_8)) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.trim().startsWith("package ") && line.contains("intrumentation")) {
                    misspelled.add(path.toString());
                    return;
                }
            }
        } catch (IOException e) {
            // Skip files we can't read
        }
    }
}
